(()=>{'use strict';function attach(){const form=document.querySelector('.ask-franklin-form');if(!form||form.querySelector('.helper-log-tools'))return false;const box=document.createElement('details');box.className='helper-log-tools';box.innerHTML='<summary><svg class="icon" aria-hidden="true"><use href="assets/icons.svg#paperclip"></use></svg>Attach a log</summary><div class="helper-log-content"><label>Choose a log file<input type="file" accept=".log,.txt,text/plain"></label><p class="helper-log-info">.log or .txt · up to 512 KB. Selecting a file does not upload it.</p><pre class="helper-log-preview" hidden></pre><p class="helper-log-note" hidden>Analyze sends a diagnostic excerpt to this website. It is processed without saving the file. Share file sends the original through an app you choose. Review personal information before continuing.</p><div class="helper-log-actions"><button type="button" class="helper-log-analyze" disabled>Analyze log</button><button type="button" class="helper-log-share" disabled>Share file</button><button type="button" class="helper-log-remove" hidden>Remove</button></div><p class="helper-log-status" role="status" aria-live="polite"></p></div>';form.insertAdjacentElement('beforebegin',box);const input=box.querySelector('input'),preview=box.querySelector('pre'),info=box.querySelector('.helper-log-info'),status=box.querySelector('.helper-log-status'),analyze=box.querySelector('.helper-log-analyze'),share=box.querySelector('.helper-log-share'),remove=box.querySelector('.helper-log-remove');let file=null,excerpt='',busy=false,version=0;const reset=()=>{version++;file=null;excerpt='';input.value='';preview.hidden=true;preview.textContent='';analyze.disabled=share.disabled=true;remove.hidden=true;box.querySelector('.helper-log-note').hidden=true;info.textContent='.log or .txt · up to 512 KB. Selecting a file does not upload it.';status.textContent='';};remove.onclick=reset;
input.onchange=async()=>{const selected=input.files[0];reset();if(!selected)return;if(!/\.(log|txt)$/i.test(selected.name)||selected.size>524288||!selected.size){status.textContent='Choose a non-empty .log or .txt file under 512 KB.';return;}const current=version;const text=await selected.text();if(current!==version)return;if(text.includes('\0')){status.textContent='This file is not a text log.';return;}file=selected;const lines=text.split(/\r?\n/),indexes=new Set();lines.forEach((l,i)=>{if(i<25||i>=lines.length-70||/fatal|error|crash|exception|signal|memory|sample count|critical archive|compat built|GTA5 UUID|stalled/i.test(l))for(let j=Math.max(0,i-1);j<=Math.min(lines.length-1,i+1);j++)indexes.add(j);});excerpt=[...indexes].sort((a,b)=>a-b).map(i=>lines[i]).join('\n').replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/ig,'[email removed]').replace(/(authorization\s*[:=]\s*|token\s*[:=]\s*|api[_-]?key\s*[:=]\s*)\S+/ig,'$1[removed]').slice(0,90000);preview.textContent=excerpt.slice(0,1800)+(excerpt.length>1800?'\n…':'');preview.hidden=false;info.textContent=selected.name+' · '+Math.ceil(selected.size/1024)+' KB · diagnostic excerpt selected';box.querySelector('.helper-log-note').hidden=false;remove.hidden=false;analyze.disabled=false;share.disabled=!(navigator.canShare&&navigator.canShare({files:[selected]}));if(share.disabled)status.textContent='File sharing is unavailable in this browser. You can attach this file manually in Discord.';};
analyze.onclick=async()=>{if(!file||busy)return;busy=true;const current=version;analyze.disabled=true;status.textContent='Checking log…';try{const r=await fetch('/api/helper',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:'Please help interpret this GTA V log excerpt:\n'+excerpt}),signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error();const data=await r.json();if(current!==version)return;const messages=document.querySelector('.ask-franklin-messages');const row=document.createElement('div');row.className='ask-franklin-message bot';const bubble=document.createElement('div');bubble.className='bubble';bubble.style.whiteSpace='pre-wrap';bubble.textContent=data.answer?.text||'No reliable match found. Share the log with the community and include your device, OS version, build and what happened.';row.append(bubble);messages?.append(row);if(messages)messages.scrollTop=messages.scrollHeight;status.textContent='Analysis complete. The file was not saved.';}catch{if(current===version)status.textContent='Private log analysis is unavailable right now. The file was not saved. You can share it with the community using Share file.';}finally{busy=false;if(current===version)analyze.disabled=!file;}};
share.onclick=async()=>{if(!file)return;try{await navigator.share({files:[file],title:'GTA V support log'});status.textContent='Share menu closed.';}catch(e){status.textContent=e.name==='AbortError'?'Sharing cancelled.':'Unable to share this file. Attach it manually in Discord.';}};return true;}
if(!document.querySelector('link[data-helper-log-style]')){const l=document.createElement('link');l.rel='stylesheet';l.href='franklin-log-files.css';l.dataset.helperLogStyle='true';document.head.append(l);}if(!attach()){const o=new MutationObserver(()=>{if(attach())o.disconnect();});o.observe(document.body,{childList:true,subtree:true});setTimeout(()=>o.disconnect(),30000);}})();
